def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    def opp(i):
        return history[i][1]

    def me(i):
        return history[i][0]

    # Fast exploitation if opponent has defected recently.
    last = opp(n - 1)
    if last == 'D':
        # Tit-for-tat with forgiveness: punish once, then cooperate again
        # unless opponent keeps defecting.
        if n >= 2 and opp(n - 2) == 'D':
            # persistent defection: defect, but occasionally test for cooperation
            if rng.random() < 0.06:
                return 'C'
            return 'D'
        return 'D'

    # Opponent just cooperated.
    # If opponent has been mostly cooperative, cooperate.
    def count_opp(x):
        c = 0
        for i in range(n):
            if opp(i) == x:
                c += 1
        return c

    c_opp = count_opp('C')
    d_opp = n - c_opp

    # Endgame: last few rounds exploit known cooperators.
    if n >= 96:
        if d_opp <= 1 and c_opp > 0:
            return 'D'
        if d_opp == 0:
            return 'D'

    # Detect long cooperative runs and exploit sparingly.
    run = 0
    for i in range(n - 1, -1, -1):
        if opp(i) == 'C':
            run += 1
        else:
            break

    if run >= 10 and n < 90:
        if rng.random() < 0.10:
            return 'D'
        return 'C'

    # If opponent has defected a lot, be defensive.
    if d_opp > c_opp + 2:
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Otherwise cooperate.
    return 'C'
